// The CLI reference on this page is generated by running the real CLI out of
// the repository root, and that CLI imports semver. This directory is its own
// project with its own lockfile, so a build that installs only this project
// leaves the root without node_modules and the first command dies on
// ERR_MODULE_NOT_FOUND. Install the root's runtime dependencies when they are
// not resolvable, which on a machine that has installed the root is never.
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const root = new URL('../', import.meta.url);
// Resolution starts where the CLI's own imports start, at the root package.
const require = createRequire(new URL('package.json', root));

const { dependencies = {} } = JSON.parse(readFileSync(new URL('package.json', root), 'utf8'));
const missing = Object.keys(dependencies).filter((name) => {
  try {
    require.resolve(name);
    return false;
  } catch {
    return true;
  }
});

if (missing.length > 0) {
  console.log(`Installing the CLI's dependencies (${missing.join(', ')}) to run it.`);
  execFileSync(
    'pnpm',
    ['install', '--dir', fileURLToPath(root), '--frozen-lockfile', '--prod', '--ignore-scripts'],
    { stdio: 'inherit' },
  );
}
